    "content": "中新网北京7月25日电 (记者 陈溯)25日，农民日报社与大疆农业在北京联合举办“数智耕大地科技兴三农——《农业无人机行业白皮书(2025/2026)》发布会”，正式发布该年度行业白皮书(以下简称《白皮书》)。《白皮书》系统梳理了2025年以来全球农业无人机行业在政策法规、技术验证、应用场景、人员培训与安全规范等方面的最新进展，围绕农业无人机规模化、多场景应用背景下的安全治理与行业发展展开交流。"
