    "description": "“东莞发布”微信公号7月25日发布关于广东东莞全市范围内实行“四停”措施的通知。 台风“红霞”来势凶猛，市三防指挥部决定自7月25日起在全市范围内实行“四停”（停课、停工、停运、停业）措施： （一）停课安排。7月25日18时起，全市中小学校、幼儿园、中等职业学校、技工院校、校外培训机构、校外托管机构、托儿所实施停课；各机构需确保通知到家长和学生，做好在校（园）人员的安全安置。 （二）停工安排。7月25日18时起，全市所有在建工地停工、工…",
    "content": "“东莞发布”微信公号7月25日发布关于广东东莞全市范围内实行“四停”措施的通知。 台风“红霞”来势凶猛，市三防指挥部决定自7月25日起在全市范围内实行“四停”（停课、停工、停运、停业）措施： （一）停课安排。7月25日18时起，全市中小学校、幼儿园、中等职业学校、技工院校、校外培训机构、校外托管机构、托儿所实施停课；各机构需确保通知到家长和学生，做好在校（园）人员的安全安置。 （二）停工安排。7月25日18时起，全市所有在建工地停工、工棚、简易宿舍内所有施工人员及管理人员撤离至安全区域。 （三）停运安排。7月25日…"
