    "author": "南方周末研究员 陈琰 实习生 施嘉敏 徐娟娟",
    "description": "在监管评价“指挥棒”指引下，当地部分银行落地了力度更大的普惠业务免责细则：若信贷出现风险，需由银行合规部门举证经办人员存在履职疏漏，方可启动追责。 南方周末研究员 陈琰 实习生 施嘉敏 徐娟娟 责任编辑：丰雨 持续8年的普惠小微贷款增速量化考核被终止。 国家金融监督管理总局近期发布《关于做好2026年小微企业金融服务工作的通知》，正式取消对银行业普惠小微企业贷款增速量化考核。普惠业务作别“冲规模”时代，驶向“提质”新阶段。 以长尾客群为…",
    "content": "在监管评价“指挥棒”指引下，当地部分银行落地了力度更大的普惠业务免责细则：若信贷出现风险，需由银行合规部门举证经办人员存在履职疏漏，方可启动追责。 新疆独特的地理格局与人口分布特点，大幅抬高了银行线下摸排、客户触达与实地尽调成本，对普惠金融下沉拓面、规模化落地构成天然约束。 受访的12家金融机构当地分支机构均积极绑定数字大模型，信用贷款的信审依据主要源自大模型算法下的农户信贷画像，以此构建普惠领域专属的信用评估体系，并在此基础上形成差异化放款额度。 南方周末研究员 陈琰 实习生 施嘉敏 徐娟娟 责任编辑：丰雨 持续…"
