    "content": "天气热了起来 又到了去路边摊大排档吃海鲜的时候 因为你吃到的生蚝可能是 假的“组装蚝”！ 实际上，生蚝挺弱鸡的 一被撬开壳，分分钟就挂了 即使不撬开壳的活生蚝 加冰也只能保鲜1-2天，然后也挂了 可想而知处理很麻烦、成本也高 于是有些店家就恶向胆边生 走上了张三的道路 只需要回收废弃的生蚝壳 再装上廉价的冷冻生蚝 就能伪装成新鲜的生蚝出售了！ 就这种超级拼装出来的蚝 一只的成本只有： 远远低于新鲜带壳生蚝 有的卖家还贴心附赠“组装攻略” 生怕店家装不明白 不够新鲜不要紧 只要多加蒜蓉辣椒掩盖味道 一盘新鲜水灵的生蚝…"
