    "description": "中新网7月25日电 据“亳州警方”微信公众号消息，7月25日，安徽亳州警方发布情况通报称，近日，有媒体报道亳州市公安局民警牛某某涉嫌违纪违法。亳州市公安局高度重视，立即成立调查组，全面开展调查复核，将根据调查结果依规依纪依法严肃处理。",
    "content": "中新网7月25日电 据“亳州警方”微信公众号消息，7月25日，安徽亳州警方发布情况通报称，近日，有媒体报道亳州市公安局民警牛某某涉嫌违纪违法。亳州市公安局高度重视，立即成立调查组，全面开展调查复核，将根据调查结果依规依纪依法严肃处理。"
