    "description": "中国防长董军星期五（7月24日）在泰国曼谷与泰国首相阿努廷会面时说，中国始终视泰国为维护地区繁荣稳定的可靠伙伴，原推动两军合作不断深化。 据新华社报道，董军说，中国愿开展具有坚实互信基础、深度合作内涵、更多战略默契的高水平协作，为维护地区持久和平稳定作出更大贡献。 根据中方新闻稿，阿努廷说，泰国感谢中国在调停泰柬冲突中发挥积极建设性作用，为和平解决争端作出贡献。 另据泰媒Khaosod报道，阿努廷之后在泰国政府大楼说，董军向他保证，中国…",
    "content": "中国防长董军星期五（7月24日）在泰国曼谷与泰国首相阿努廷会面时说，中国始终视泰国为维护地区繁荣稳定的可靠伙伴，原推动两军合作不断深化。 据新华社报道，董军说，中国愿开展具有坚实互信基础、深度合作内涵、更多战略默契的高水平协作，为维护地区持久和平稳定作出更大贡献。 根据中方新闻稿，阿努廷说，泰国感谢中国在调停泰柬冲突中发挥积极建设性作用，为和平解决争端作出贡献。 另据泰媒Khaosod报道，阿努廷之后在泰国政府大楼说，董军向他保证，中国向柬埔寨提供的军事装备属于正常商业销售，并非用来展开针对泰国的用途。 阿努廷也说…"
