    "title": "景德镇十二时辰",
    "link": "http://www.news.cn/20260725/0e6c7a0fc35b4e96aac7bb448c95e20d/c.html",
    "pub_date": "2026-07-25 13:47:54",
    "author": "胡晨欢,朱雨诺,王迪迩,眭黎曦",
    "description": "往昔昌南， 千年窑火不熄的源头， 连通欧亚的瓷韵纽带。 今朝景德镇， 活态传承的创意之都， 世界在此对话泥土与火焰。 寻路千年瓷都， 相逢景德镇十二时辰。 监制：赵卓昀 李兴文 统筹：郑开君 李劲峰 记者：王迪迩 眭黎曦 胡晨欢 朱雨诺 新华社国际部 江西分社 迪迩工作室 联合出品",
    "content": "往昔昌南， 千年窑火不熄的源头， 连通欧亚的瓷韵纽带。 今朝景德镇， 活态传承的创意之都， 世界在此对话泥土与火焰。 &nbsp; 寻路千年瓷都， 相逢景德镇十二时辰。 &nbsp; 监制：赵卓昀 李兴文 统筹：郑开君 李劲峰 记者：王迪迩 眭黎曦 胡晨欢 朱雨诺 新华社国际部 江西分社 迪迩工作室 联合出品"
