    "content": "新华社北京7月25日电 题：依法惩治行业垄断 护航平台经济发展 新华社记者赵怡宁、戴小河 7月25日，市场监管总局依法对携程集团有限公司滥用市场支配地位实施垄断行为作出行政处罚，罚没款合计51.79亿元。监管部门对垄断行为坚定亮剑，传递出引导平台经济持续健康发展的鲜明信号，为维护公平竞争的市场秩序筑牢防线。 网络预订平台凭借其选择和比价空间丰富等优势，为消费者提供了便利，也助推酒店行业不断提升服务质量。然而，一段时间以来，个别头部平台为谋取更大利益，凭借流量霸权与定价特权，挤压商户经营空间，出现了一些通过不公平竞争…"
