    "content": "近日，记者走进西藏海拔4500米那曲嘉黎乡村与云南玉龙雪山脚下校园，记录两地少年的足球故事。场地简陋，却奔涌着滚烫的热爱。高原与雪山间，少年们奋力奔跑，追逐属于自己的足球梦想。 ■我在“高原世界杯”当观众 全球目光聚焦世界杯赛场，足球的热情席卷世界各地。而在平均海拔4500米以上的西藏那曲市嘉黎县，这里的孩子们也拥有一场独属于高原的“世界杯”。 没有专业绿茵场，孩子们把凹凸不平的牛圈泥地当作球场；没有工艺精良的赛事奖杯，他们就地取材，用蔬菜创造高原版“大力神杯”……高寒缺氧、环境艰苦，却从未冲淡少年们心底滚烫的足球…"
