    "description": "新华社北京7月25日电 题：让平台经济规范向好——市场监管总局对携程实施垄断行为依法作出行政处罚 新华社“新华视点”记者戴小河、程思琪、王悦阳 国家市场监督管理总局25日通报，依据《中华人民共和国反垄断法》相关规定，对携程集团有限公司滥用市场支配地位实施垄断行为作出行政处罚，没收违法所得16.58亿元，并处以罚款35.21亿元，罚没款合计51.79亿元。同时，责令企业立即停止违法行为，全额退还强制扣除酒店经营者的订单储备金1.22亿元，…",
    "content": "新华社北京7月25日电 题：让平台经济规范向好——市场监管总局对携程实施垄断行为依法作出行政处罚 新华社“新华视点”记者戴小河、程思琪、王悦阳 国家市场监督管理总局25日通报，依据《中华人民共和国反垄断法》相关规定，对携程集团有限公司滥用市场支配地位实施垄断行为作出行政处罚，没收违法所得16.58亿元，并处以罚款35.21亿元，罚没款合计51.79亿元。同时，责令企业立即停止违法行为，全额退还强制扣除酒店经营者的订单储备金1.22亿元，要求企业全面整改并公开整改措施。 这是我国在线旅游行业反垄断第一案，是新型垄断行…"
