    "content": "新华社北京7月25日电 连日来，法国和西班牙境内野火肆虐，截至24日仍有多处火场。在法国西南部，超过6万名居民被迫逃离家园，一处旅游胜地的居民和游客被要求全体撤离；西班牙首都马德里附近村庄疏散约1万人，西班牙政府24日宣布进入国家紧急状态。两国已向欧盟请求支援。 法国西南部吉伦特省费雷角半岛接到全体疏散的命令。这座半岛是大西洋沿岸一处旅游胜地，由于正值夏季度假高峰期，当地露营地和民宿住满了游客。政府派遣船只，将遭受野火威胁的居民和游客转移到安全地带。 法国总统马克龙24日在社交媒体上发帖说，由于全国多地野火持续蔓延…"
