    "content": "新华社北京7月25日电 韩国首尔高等法院24日对SK集团会长崔泰源与前妻卢素英离婚财产分割案作出重审判决，要求崔泰源向卢素英支付9440亿韩元（约合43亿元人民币）。这一金额创韩国离婚财产分割纪录，但低于该法院2024年二审判决的1.38万亿韩元（约合64亿元人民币）。 崔泰源1988年与时任韩国总统卢泰愚之女卢素英结婚，婚后育有三名子女。崔泰源2015年承认有婚外情，2017年发起离婚相关法律程序。韩国最高法院去年10月裁定两人解除婚姻关系，并维持二审判决中男方向女方支付20亿韩元（约合920万元人民币）精神损害…"
