    "description": "新华社科威特城7月25日电 也门胡塞武装25日在社交媒体发表声明称，使用导弹打击了沙特阿拉伯南部城市贾赞。 沙特民防部门当天向贾赞和位于红海沿岸的延布市居民发布安全警报，数分钟后宣布警报解除。 胡塞武装20日宣布对沙特实施海上禁运，并警告国际航运公司称，与沙特港口开展贸易往来的船只可能面临军事打击。",
