    "content": "当地时间25日，在韩国釜山召开的联合国教科文组织第48届世界遗产大会上，中国提交的“景德镇手工瓷业遗存”项目顺利通过审议，成功列入《世界遗产名录》。至此，中国世界遗产总数达61项。 记者：陈怡 报道员：金颢旼、杨畅、孙一然 新华社音视频部制作"
