    "content": "新华社吉尔吉斯斯坦乔尔蓬阿塔7月24日电 上海合作组织成员国外交部长理事会声明 上海合作组织（以下简称“上合组织”或“组织”）成员国外交部长于2026年7月24日在吉尔吉斯共和国乔尔蓬阿塔举行会 议，就深化政治、安全、经济和人文领域合作，以及当前国际和地区热点问题进行讨论，重申上合组织坚定奉行不针对其他国家和组织，相互尊重主权、独立、领土完整，不干涉内政，在国际事务中不使用武力或以武力相威胁的原则，并声明如下： 今年上合组织各项工作均围绕组织成立25周年这一主线展开。历经多年发展，上合组织已经成为具有影响力且蓬勃发…"
