    "description": "《澎湃新闻｜艺术评论》获悉，2026年7月25日11时44分，在韩国釜山举行的联合国教科文组织世界遗产委员会第48届大会上，“景德镇手工瓷业遗存”成功通过审议，列入世界遗产项目，成为中国第61项世界遗产，“景德镇手工瓷业遗存”是由景德镇镇区瓷业生产中心、湖田古瓷窑址、高岭瓷土矿遗址、长岭瓷石矿遗址和蛟潭窑柴燃料产区5大片区组成，完整保留了10至19世纪手工制瓷全产业链体系，历经11年申遗之路，这一项目列入世界遗产后，填补了《世界遗产名录…",
    "content": "《澎湃新闻｜艺术评论》获悉，2026年7月25日11时44分，在韩国釜山举行的联合国教科文组织世界遗产委员会第48届大会上，“景德镇手工瓷业遗存”成功通过审议，列入世界遗产项目，成为中国第61项世界遗产，“景德镇手工瓷业遗存”是由景德镇镇区瓷业生产中心、湖田古瓷窑址、高岭瓷土矿遗址、长岭瓷石矿遗址和蛟潭窑柴燃料产区5大片区组成，完整保留了10至19世纪手工制瓷全产业链体系，历经11年申遗之路，这一项目列入世界遗产后，填补了《世界遗产名录》中“瓷”主题遗产的空白。 联合国教科文组织世界遗产委员会第48届大会审议通过“…"
