    "content": "新华社广州7月25日电（记者熊嘉艺）记者25日上午从广东省水利厅了解到，鉴于今年第12号台风“红霞”强度继续加强，进一步趋向粤东沿海，将给广东带来严重风雨浪潮影响，根据《广东省水利厅水旱灾害防御工作规则》，广东省水利厅水旱灾害防御领导小组定于7月25日9时将水利防汛防台风Ⅲ级应急响应提升至Ⅱ级。 广东省水文局有关负责人介绍，受台风“红霞”影响，预计7月25日至28日，广东省北部、中东部和粤东沿海地区部分河流可能出现3至8米的涨水过程，北江、东江、韩江干流将出现明显涨水过程，北江、东江、韩江、粤东沿海等流域内部分中小…"
