    "author": "澎湃新闻记者 胡含嫣",
    "description": "黄仁勋在X（原推特）平台上发布了自己的第一条推文。 当地时间7月24日，AI（人工智能）芯片龙头英伟达CEO黄仁勋在X上首次发布推文，并附上一封包含众多科技巨头签名的公开信，针对美国AI监管界围绕开源AI的近期争论，为开源展开全面辩护，阐述开源模型的重要性。 黄仁勋写道：“AI将变革每一个行业，赋能每一家公司，并被每一个国家所构建。开源模型能强化安全性与网络安全，加速创新与普及，并实现主权。世界既需要前沿的闭源模型，也需要前沿的开源模型…",
    "content": "黄仁勋在X（原推特）平台上发布了自己的第一条推文。 当地时间7月24日，AI（人工智能）芯片龙头英伟达CEO黄仁勋在X上首次发布推文，并附上一封包含众多科技巨头签名的公开信，针对美国AI监管界围绕开源AI的近期争论，为开源展开全面辩护，阐述开源模型的重要性。 黄仁勋写道：“AI将变革每一个行业，赋能每一家公司，并被每一个国家所构建。开源模型能强化安全性与网络安全，加速创新与普及，并实现主权。世界既需要前沿的闭源模型，也需要前沿的开源模型。” 来源：X 黄仁勋在推文中附上了一封联合公开信，标题为《开放权重与美国在AI…"
