    "title": "华润集团原党委委员、副总经理韩嵩严重违纪违法被开除党籍和公职",
    "link": "http://www.news.cn/20260725/24712c92de1f4156877c6742372a030b/c.html",
    "pub_date": "2026-07-25 11:15:41",
