    "content": "新华社北京7月25日电 经中共中央批准，中央纪委国家监委对华润（集团）有限公司原党委委员、副总经理韩嵩严重违纪违法问题进行了立案审查调查。 经查，韩嵩丧失理想信念，背弃初心使命，搞迷信活动；违反中央八项规定精神，多次接受可能影响公正执行公务的宴请和旅游安排，接受管理和服务对象提供的出行服务；在职务晋升、职工录用工作中为他人谋取利益；廉洁底线失守，违规收受礼品、消费卡，纵容、默许亲属违规取酬；违规干预和插手市场经济活动；毫无纪法底线，将权力异化为谋取个人私利的工具，大搞权钱交易，利用职务便利为他人在项目承揽、职务晋升…"
