    "content": "2025年全省互联网客运发班班次、客运量分别同比增长近70%。 打造全省统一的出行服务入口，计划8月底前上线运行。 南方周末记者 周小铃 责任编辑：张玥 7月14日，广州嘉禾望岗H出口停靠点的两辆巴士。南方周末记者 周小铃 摄 广东的客运大巴复苏，逐渐成为全国关注的现象。 一位家住广州番禺，上班在深圳的乘客告诉南方周末记者，他一开始自驾通勤，之后变成高铁通勤，再后来发现大巴是最优选择，“开车又累又贵，到高铁站要转很久车，这个（大巴）便宜”。 2026年6月26日，在广州天河客运站，一位赶来乘车的广东技术师范大学的大…"
