    "content": "中国最大的线上旅游平台携程涉嫌实施反垄断行为，被官方处以逾51亿元人民币（9.72亿新元）罚款，并被要求全面整改。携程回应称，将诚恳接受、坚决服从官方监管要求。 中国国家市场监督管理总局星期六（7月25日）在官网公告，该局当天依法对携程集团有限公司（简称携程）滥用市场支配地位实施垄断行为作出行政处罚，罚没款合计51.79亿元。 市场监管总局今年1月通报，依据《中国反垄断法》对携程涉嫌滥用市场支配地位实施垄断行为立案调查。携程当时回应称，公司将积极配合监管部门调查，全面落实监管要求，与行业各方携手共建可持续发展的市场…"
