    "content": "新华社广州7月25日电（记者胡拿云）鉴于今年第12号台风“红霞”强度继续加强，进一步趋向粤东沿海，将给广东带来严重的风雨浪潮影响。广东省防汛防旱防风总指挥部于25日9时将防风应急响应提升至Ⅱ级。 广东省气象台监测，台风“红霞”已于25日5时加强为台风级。25日8时，其中心位于广东省汕尾市东南方向约380公里的南海北部海面上，预计，“红霞”将以20公里左右的时速向西偏北方向快速移动，强度逐渐加强，将于25日夜间到26日早晨以台风或强台风级（12至14级）在惠来到深圳沿海登陆，之后逐渐转向北偏西方向移动，强度逐渐减弱。…"
