    "title": "Waymo正考虑终止与Uber的合作关系",
    "link": "https://36kr.com/newsflashes/3910429485143429?f=rss",
    "pub_date": "2026-07-25 10:40:03",
    "author": "",
    "description": "据报道，Alphabet旗下的Waymo正在探索退出与Uber合作关系的可能性。Waymo于2023年5月首次与Uber合作，在美国亚利桑那州凤凰城推出无人驾驶出租车服务。随后，双方又在奥斯汀和亚特兰大达成合作协议，在这些地区，Waymo的车辆只能通过Uber应用程序使用，Uber与合作伙伴Avomo共同管理车队。今年5月，Uber和Waymo在凤凰城的合作已于协议到期后终止。（界面新闻）",
    "content": "据报道，Alphabet旗下的Waymo正在探索退出与Uber合作关系的可能性。Waymo于2023年5月首次与Uber合作，在美国亚利桑那州凤凰城推出无人驾驶出租车服务。随后，双方又在奥斯汀和亚特兰大达成合作协议，在这些地区，Waymo的车辆只能通过Uber应用程序使用，Uber与合作伙伴Avomo共同管理车队。今年5月，Uber和Waymo在凤凰城的合作已于协议到期后终止。（界面新闻）"
