    "author": "黄扬",
    "description": "新华社台北7月25日电（记者黄扬、褚萌萌）电影《给阿嬷的情书》将于8月中旬亮相2026桃园电影节，这也是该片在台湾的首次公开放映。 据桃园电影节官网信息，该片入选“特别放映”单元，将于8月15日和16日放映共计两场。 影片以潮汕方言为主，围绕“侨批”主线，讲述老一辈华侨下南洋谋生时与家乡亲人彼此牵挂、守望相助的动人故事。 影片自上映以来，凭借细腻的情感刻画与真挚的故事内核引发广泛共鸣。截至目前，该片全球累计票房已突破21亿元人民币。 该…",
    "content": "新华社台北7月25日电（记者黄扬、褚萌萌）电影《给阿嬷的情书》将于8月中旬亮相2026桃园电影节，这也是该片在台湾的首次公开放映。 据桃园电影节官网信息，该片入选“特别放映”单元，将于8月15日和16日放映共计两场。 影片以潮汕方言为主，围绕“侨批”主线，讲述老一辈华侨下南洋谋生时与家乡亲人彼此牵挂、守望相助的动人故事。 影片自上映以来，凭借细腻的情感刻画与真挚的故事内核引发广泛共鸣。截至目前，该片全球累计票房已突破21亿元人民币。 该片“入岛”消息公布后，不少曾赴大陆观影的台湾民众在网络留言力挺，称其为“难得的好…"
