    "content": "新华社海口7月24日电（记者曹奕博、杨冠宇）在24日进行的国际团结杯比赛中，中国男篮12人全部登场并得分，以113:79大胜喀麦隆队，赢得赛事“开门红”。 7月24日，中国队球员赵继伟在比赛中。 中国队的杨瀚森和王俊杰在海外训练缺席本次比赛，年轻球员李悦洲进入球队12人大名单。来访的喀麦隆队保留了男篮世界杯非洲区预选赛第一阶段阵容中的多名后场球员，并补强了上赛季效力于美职篮波士顿凯尔特人队的得分后卫约翰·通杰。 中国男篮开场手感火热，贺希宁和李弘权接连命中远投，帮助主队打出11:0的“梦幻开局”。陷入得分荒的喀麦隆…"
