    "content": "新华社华盛顿7月24日电 美职篮（NBA）历史得分王勒布朗·詹姆斯24日通过个人社交媒体宣布，41岁的他将以自由球员身份加盟费城76人。 5月11日，勒布朗·詹姆斯（左）在比赛中带球进攻。新华社发（赵汉荣摄） 自从詹姆斯今夏宣布离开洛杉矶湖人成为自由球员，他的去向就成为全联盟的一大焦点，就连NBA总裁亚当·萧华都公开表示，希望詹姆斯尽快决定自己的前途，从而方便联盟安排新赛季的赛程。 据美国媒体报道，詹姆斯将和76人队签下一份两年价值800万美元的合同，他上赛季效力湖人队期间，场均能贡献20.9分，7.2次助攻和6.…"
