    "content": "新华社布达佩斯7月24日电（记者周欣）2026赛季世界一级方程式赛车锦标赛（F1）匈牙利大奖赛24日在亨格罗林赛道进行了前两次自由练习赛。法拉利车手勒克莱尔和汉密尔顿分别跑出两次练习赛最快圈速，帮助车队包揽首个比赛日两次练习赛头名。 7月23日，法拉利车队车手勒克莱尔（前）出席媒体日活动。新华社发（鲍洛格·达维德摄） 在当天进行的第一次自由练习赛中，英国大奖赛冠军勒克莱尔延续良好状态，以1分19秒075的最快圈速排名第一，红牛车手维斯塔潘和法拉利车手汉密尔顿分列第二、第三位。 第二次自由练习赛中，法拉利车手占据前两…"
