    "content": "新华社伦敦7月24日电（记者马邦杰）英超曼城新任主教练马雷斯卡24日表示，球队中场罗德里将于下周一接受背部手术，随后进入休整和康复阶段，具体复出时间尚未确定。 7月19日，西班牙队球员罗德里在颁奖仪式上亲吻大力神杯。新华社记者 黄宗治 摄 现年30岁的罗德里日前随西班牙队夺得世界杯冠军，并获得世界杯金球奖。不过，近年来他饱受伤病困扰。此前因前十字韧带重伤长期缺阵，上赛季又多次受到伤病影响，出场时间受到限制。尽管如此，罗德里在世界杯期间状态出色，成为西班牙队夺冠的功臣。 这是马雷斯卡出任曼城主帅后的首次新闻发布会。他…"
