    "author": "",
    "description": "中国中央气象台发布台风橙色预警，称台风“红霞”已于星期六早晨由强热带风暴级加强为台风级，将在香港到广东惠来一带沿海登陆。 据中央气象台预报，“红霞”星期六（7月25日）早晨5点钟其中心位于广东汕尾东南方向约450公里的南中国海东北部海面上，并将以每小时20公里左右的速度向西偏北方向移动，强度逐渐加强，并向粤东沿海靠近。 气象台预计，“红霞”可能在星期六夜间至星期天（26日）早晨在香港到广东惠来一带沿海登陆，登陆后转向偏北方向移动，强度逐…",
    "content": "中国中央气象台发布台风橙色预警，称台风“红霞”已于星期六早晨由强热带风暴级加强为台风级，将在香港到广东惠来一带沿海登陆。 据中央气象台预报，“红霞”星期六（7月25日）早晨5点钟其中心位于广东汕尾东南方向约450公里的南中国海东北部海面上，并将以每小时20公里左右的速度向西偏北方向移动，强度逐渐加强，并向粤东沿海靠近。 气象台预计，“红霞”可能在星期六夜间至星期天（26日）早晨在香港到广东惠来一带沿海登陆，登陆后转向偏北方向移动，强度逐渐减弱。 中央气象台也发布暴雨橙色预警，星期六早8时至星期天早8时，广东东部和南…"
