    "content": "新华社北京7月25日电（记者戴小河、赵怡宁）国家市场监督管理总局25日通报，依据《中华人民共和国反垄断法》相关规定，对携程集团有限公司滥用市场支配地位实施垄断行为作出行政处罚，没收违法所得16.58亿元，并处以罚款35.21亿元。同时，责令其全额退还强制扣除酒店经营者的订单储备金1.22亿元，要求企业全面整改并公开整改措施。 携程是我国目前最大的在线旅游平台，主营业务涵盖酒店预订、交通票务、旅游度假等领域。2025年以来，市场监管总局陆续收到针对携程涉嫌垄断的举报，反映携程迫使酒店商家接受霸王条款，还利用技术手段操…"
