    "description": "国家市场监督管理总局7月25日通报，依据《中华人民共和国反垄断法》相关规定，对携程集团有限公司滥用市场支配地位实施垄断行为作出行政处罚，没收违法所得16.58亿元，并处以罚款35.21亿元，罚没款合计51.79亿元。同时，责令企业立即停止违法行为，全额退还强制扣除酒店经营者的订单储备金1.22亿元，要求企业全面整改并公开整改措施。 记者：王悦阳、戴小河、赵怡宁 海报制作：胡戈 新华社国内部出品",
